/**
 * Industry CMA benchmark snapshot — typed loader.
 *
 * Data lives in benchmarks.json, regenerated by scripts/refresh_benchmarks.py
 * from the providers' latest public publications. Values are 10-year (JPM
 * 10–15y) NOMINAL expected returns in percentage points, mapped to the tool's
 * 10 asset-class buckets via the closest provider proxy.
 *
 * IMPORTANT — read `return_basis` / `notes` before comparing:
 *   • BlackRock & J.P. Morgan are GEOMETRIC; State Street is ARITHMETIC
 *     (~0.5·σ² higher for equities).
 *   • J.P. Morgan's horizon is 10–15y, not exactly 10y.
 *   • Non-base-currency bonds are currency-hedged (BlackRock, JPM); SSGA
 *     equities are local-currency (no FX translation), and its EUR coverage
 *     is partial (null cells).
 */

import type { AssetClass, BaseCurrency } from './types';
import benchmarksJson from './benchmarks.json';

export type BenchmarkProviderId = 'blackrock' | 'jpmorgan' | 'ssga';
export type ReturnBasis = 'geometric' | 'arithmetic';

export interface BenchmarkCell {
  /** 10-year expected return in percentage points, or null if no clean proxy exists. */
  value: number | null;
  /** The provider line item used as the proxy for this bucket. */
  proxy: string;
}

export interface ProviderBenchmark {
  name: string;
  publication: string;
  /** Forecast horizon label, e.g. "10y" or "10-15y". */
  horizon: string;
  return_basis: ReturnBasis;
  fees: string;
  source_url: string;
  notes: string;
  /** ISO date the underlying data is "as of". */
  as_of: string;
  returns: Record<BaseCurrency, Partial<Record<AssetClass, BenchmarkCell>>>;
}

export interface BenchmarksFile {
  schema_version: number;
  /** ISO date the snapshot was generated. */
  generated: string;
  disclaimer: string;
  buckets: AssetClass[];
  providers: Record<BenchmarkProviderId, ProviderBenchmark>;
}

export const BENCHMARKS = benchmarksJson as unknown as BenchmarksFile;

export const BENCHMARK_PROVIDER_IDS: BenchmarkProviderId[] = [
  'blackrock',
  'jpmorgan',
  'ssga',
];

/** One provider's value for a bucket in the given base currency (or null). */
export function getBenchmark(
  provider: BenchmarkProviderId,
  currency: BaseCurrency,
  bucket: AssetClass,
): BenchmarkCell | null {
  return BENCHMARKS.providers[provider]?.returns[currency]?.[bucket] ?? null;
}

export interface BenchmarkComparisonRow {
  bucket: AssetClass;
  /** provider id -> cell (value may be null where no clean proxy exists). */
  providers: Record<BenchmarkProviderId, BenchmarkCell | null>;
}

/**
 * Per-bucket comparison rows for a base currency — convenient for rendering a
 * "your result vs providers" table alongside the engine output.
 */
export function getComparisonRows(currency: BaseCurrency): BenchmarkComparisonRow[] {
  return BENCHMARKS.buckets.map((bucket) => ({
    bucket,
    providers: BENCHMARK_PROVIDER_IDS.reduce(
      (acc, id) => {
        acc[id] = getBenchmark(id, currency, bucket);
        return acc;
      },
      {} as Record<BenchmarkProviderId, BenchmarkCell | null>,
    ),
  }));
}
